-- Тема 11: варианты ответов выровнены по длине и форме (49 исправлений в 15 вопросах), ключи не меняются.
-- Источник: scripts/questions/079_option_length_topic11.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('option', 'Как изменить предельный размер сегмента файла данных?', 'Параметром в postgresql.conf', 'Параметром segment_size в postgresql.conf', 'Параметр segment_size только показывает размер, заданный при сборке; изменить его нельзя.', NULL),
        ('option', 'Как изменить предельный размер сегмента файла данных?', 'Командой ALTER SYSTEM', 'Командой ALTER SYSTEM SET segment_size', 'ALTER SYSTEM не меняет параметр segment_size: он только для чтения.', NULL),
        ('option', 'Как изменить предельный размер сегмента файла данных?', 'Только при сборке сервера из исходных кодов (--with-segsize)', 'Пересборкой сервера (--with-segsize)', 'Размер задаётся при сборке.', 'Размер сегмента задаётся при сборке сервера из исходных кодов ключом --with-segsize.'),
        ('option', 'Как изменить предельный размер сегмента файла данных?', 'Ключом initdb', 'Ключом при вызове утилиты initdb', 'У initdb такого ключа нет; --wal-segsize меняет сегмент журнала, а не данных.', NULL),
        ('option', 'Для каких объектов существует слой инициализации (init)?', 'Для всех таблиц', 'Для всех таблиц и индексов обычных баз', 'Обычным журналируемым таблицам он не нужен.', NULL),
        ('option', 'Для каких объектов существует слой инициализации (init)?', 'Для временных таблиц', 'Для временных таблиц и индексов сеанса', 'Временным таблицам он не нужен.', NULL),
        ('option', 'Для каких объектов существует слой инициализации (init)?', 'Только для индексов', 'Для индексов любых таблиц, но не самих таблиц', 'Не только для индексов.', 'Слой init есть не только у индексов: он есть и у нежурналируемых таблиц и последовательностей.'),
        ('option', 'Для каких объектов существует слой инициализации (init)?', 'Только для нежурналируемых объектов: таблиц, их индексов и последовательностей', 'Для нежурналируемых таблиц и их индексов', 'По нему объект после сбоя возвращается в начальное состояние: таблица пустая, последовательность с начальным значением.', 'Слой init есть у нежурналируемых объектов: таблиц, их индексов и последовательностей. По нему объект после сбоя возвращается в начальное состояние: таблица пустая, последовательность с начальным значением.'),
        ('option', 'Сколько файлов у небольшой обычной таблицы, когда у неё уже созданы карты свободного пространства и видимости? Индексы и TOAST не считаются.', 'Один', 'Один: основной слой без карт', 'Кроме основного слоя есть карты.', 'Кроме основного слоя есть карты свободного пространства и видимости.'),
        ('option', 'Сколько файлов у небольшой обычной таблицы, когда у неё уже созданы карты свободного пространства и видимости? Индексы и TOAST не считаются.', 'Три: основной слой, карта свободного пространства и карта видимости', 'Три: основной слой и две карты', 'Карта видимости обычно появляется после первой очистки.', NULL),
        ('option', 'Сколько файлов у небольшой обычной таблицы, когда у неё уже созданы карты свободного пространства и видимости? Индексы и TOAST не считаются.', 'Два', 'Два: основной слой и карта видимости', 'После очистки файлов обычно три.', 'После очистки файлов обычно три: карта видимости появляется после первой очистки.'),
        ('option', 'Сколько файлов у небольшой обычной таблицы, когда у неё уже созданы карты свободного пространства и видимости? Индексы и TOAST не считаются.', 'Четыре', 'Четыре: основной слой, карты и init', 'Слой init есть только у нежурналируемых таблиц.', NULL),
        ('option', 'Что происходит с нежурналируемой таблицей после сбоя?', 'Восстанавливается из WAL', 'Восстанавливается из записей WAL после сбоя', 'Изменения такой таблицы в журнал не пишутся.', NULL),
        ('option', 'Что происходит с нежурналируемой таблицей после сбоя?', 'Удаляется вместе с определением', 'Удаляется вместе с определением таблицы', 'Определение таблицы сохраняется.', NULL),
        ('option', 'Что происходит с нежурналируемой таблицей после сбоя?', 'Помечается как повреждённая', 'Помечается как повреждённая до очистки', 'Ничего не помечается.', NULL),
        ('option', 'Что происходит с нежурналируемой таблицей после сбоя?', 'Она становится пустой: слой init записывается на место основного', 'Становится пустой: init копируется на основной слой', 'Таблица остаётся, но без данных.', 'Таблица остаётся, но без данных: слой init записывается на место основного.'),
        ('option', 'Что такое TOAST?', 'Формат журнала предзаписи', 'Формат журнала предзаписи и архива WAL', 'Журнал — это WAL.', NULL),
        ('option', 'Что такое TOAST?', 'Тип индекса', 'Тип индекса для длинных значений текста', 'Это не тип индекса.', 'Это не тип индекса: TOAST относится к хранению значений.'),
        ('option', 'Что такое TOAST?', 'Механизм хранения длинных значений: сжатие и/или вынос в отдельную таблицу', 'Хранение длинных значений вне страницы', 'Так длинные значения не мешают версии строки поместиться на страницу.', 'Механизм хранения длинных значений: сжатие и/или вынос в отдельную таблицу. Так длинные значения не мешают версии строки поместиться на страницу.'),
        ('option', 'Что такое TOAST?', 'Утилита резервного копирования', 'Утилита логического резервного копирования', 'Это не утилита.', NULL),
        ('option', 'Что показывает функция pg_table_size?', 'Только размер основного слоя', 'Размер основного слоя без дополнительных слоёв', 'Так работает pg_relation_size без второго аргумента.', NULL),
        ('option', 'Что показывает функция pg_table_size?', 'Размер таблицы со всеми индексами', 'Размер таблицы со всеми её индексами', 'Это pg_total_relation_size.', NULL),
        ('option', 'Что показывает функция pg_table_size?', 'Только размер индексов', 'Суммарный размер индексов таблицы', 'Это pg_indexes_size.', NULL),
        ('option', 'Что показывает функция pg_table_size?', 'Размер таблицы вместе с toast-частью, но без обычных индексов', 'Размер таблицы с toast-частью, без индексов', 'Все слои таблицы и её toast-часть.', 'Все слои таблицы и её toast-часть, без обычных индексов.'),
        ('option', 'Какая функция показывает полный размер таблицы вместе со всеми индексами?', 'pg_relation_size', 'Функция pg_relation_size', 'Размер одного слоя.', NULL),
        ('option', 'Какая функция показывает полный размер таблицы вместе со всеми индексами?', 'pg_total_relation_size', 'Функция pg_total_relation_size', 'Таблица, toast-часть и все индексы.', NULL),
        ('option', 'Какая функция показывает полный размер таблицы вместе со всеми индексами?', 'pg_table_size', 'Функция pg_table_size', 'Без индексов самой таблицы (индекс toast-таблицы учитывается).', NULL),
        ('option', 'Какая функция показывает полный размер таблицы вместе со всеми индексами?', 'pg_indexes_size', 'Функция pg_indexes_size', 'Только индексы.', NULL),
        ('option', 'Какие утверждения верны о системном столбце ctid обычной таблицы?', 'Он подходит как неизменный идентификатор строки на весь срок её жизни', 'Он подходит как постоянный идентификатор строки', 'UPDATE и перемещение при VACUUM FULL могут изменить ctid; для логической идентификации нужен ключ.', NULL),
        ('option', 'Какие утверждения верны о системном столбце ctid обычной таблицы?', 'Он уникален среди всех таблиц базы данных', 'Он уникален среди строк всех таблиц базы данных', 'Физические адреса ctid могут совпадать в разных таблицах.', NULL),
        ('option', 'Какие утверждения верны о системном столбце ctid обычной таблицы?', 'Он указывает физическое расположение конкретной версии строки внутри таблицы', 'Он указывает расположение версии строки в таблице', 'ctid позволяет найти версию строки в файлах таблицы.', NULL),
        ('option', 'Что верно для TOAST?', 'Обычный SELECT может читать короткие столбцы основной таблицы без чтения вынесенных значений из TOAST', 'SELECT может читать короткие столбцы без чтения TOAST', 'Если SELECT не использует длинное поле в результате, условиях или других вычислениях, извлекать его значение из TOAST не требуется.', 'Если SELECT не использует длинное поле в результате, условиях или других вычислениях, извлекать его значение из TOAST не требуется: обычный SELECT может читать короткие столбцы основной таблицы без чтения вынесенных значений.'),
        ('option', 'Как называется первый файл основного слоя постоянной таблицы?', 'Именем таблицы', 'Именем таблицы в схеме', 'Файлы называются по числовому идентификатору, а не по имени.', NULL),
        ('option', 'Почему важно, что файлы всех объектов одной базы и одного табличного пространства лежат в одном каталоге?', 'Файловые системы могут плохо работать с очень большим числом файлов в каталоге', 'Файловые системы плохо справляются с множеством файлов', 'Это нужно учитывать при большом числе объектов.', 'Это нужно учитывать при большом числе объектов: в одном каталоге могут лежать файлы всех таблиц и индексов базы.'),
        ('option', 'Почему важно, что файлы всех объектов одной базы и одного табличного пространства лежат в одном каталоге?', 'PostgreSQL блокирует весь каталог при записи', 'PostgreSQL блокирует весь каталог при записи файла', 'Такой блокировки нет.', NULL),
        ('option', 'Какое ограничение действует на размер версии строки?', 'Ограничений нет', 'Ограничений нет, но длинные значения выносятся', 'Версия строки должна помещаться на страницу.', 'Версия строки должна помещаться на страницу; длинные значения выносятся механизмом TOAST.'),
        ('option', 'Какое ограничение действует на размер версии строки?', 'Она может занимать до 1 ГБ', 'Она может занимать до 1 ГБ на странице', 'Около 1 ГБ — предел отдельного значения поля, а хранимая версия строки должна помещаться на странице.', NULL),
        ('option', 'Какое ограничение действует на размер версии строки?', 'Она должна целиком помещаться на одну страницу', 'Она должна помещаться на одну страницу', 'Для длинных значений применяется TOAST.', 'Версия строки целиком помещается на одну страницу; для длинных значений применяется TOAST.'),
        ('option', 'Строка с длинным значением обновляется, но само длинное значение не меняется. Что происходит в toast-таблице?', 'Новая версия строки ссылается на то же значение в toast-таблице', 'Новая версия строки ссылается на то же значение', 'У toast-таблицы своя версионность, и это экономит место.', 'Новая версия строки ссылается на то же значение в toast-таблице: у неё своя версионность, и это экономит место.'),
        ('option', 'Строка с длинным значением обновляется, но само длинное значение не меняется. Что происходит в toast-таблице?', 'Старое значение сразу удаляется', 'Старое значение сразу удаляется из toast-таблицы', 'На него продолжает ссылаться новая версия строки.', NULL),
        ('option', 'Строка с длинным значением обновляется, но само длинное значение не меняется. Что происходит в toast-таблице?', 'Значение переносится в основную таблицу', 'Значение переносится в основную таблицу при UPDATE', 'Длинное значение остаётся в toast-таблице.', NULL),
        ('option', 'Почему pg_database_size возвращает больше, чем сумма размеров пользовательских таблиц базы?', 'pg_database_size учитывает журнал предзаписи', 'pg_database_size учитывает журнал предзаписи кластера', 'Журнал общий для кластера и в размер базы не входит.', NULL),
        ('option', 'Почему pg_database_size возвращает больше, чем сумма размеров пользовательских таблиц базы?', 'Функция завышает результат', 'Функция завышает результат из-за округления', 'Функция считает размер точно.', NULL),
        ('option', 'Почему pg_database_size возвращает больше, чем сумма размеров пользовательских таблиц базы?', 'В размер базы входят также системный каталог и другие служебные объекты', 'В размер входят системный каталог и служебные объекты', 'В каждой базе есть свои таблицы каталога и их индексы.', 'В размер базы входят также системный каталог и другие служебные объекты: в каждой базе есть свои таблицы каталога и их индексы.'),
        ('option', 'Почему pg_database_size возвращает больше, чем сумма размеров пользовательских таблиц базы?', 'В размер базы входит буферный кеш', 'В размер базы входит содержимое буферного кеша', 'Буферный кеш находится в памяти.', NULL),
        ('option', 'В какой схеме лежит toast-таблица временной таблицы?', '`pg_temp_N`', 'Схема pg_temp_N сеанса', 'Это временная схема самих временных таблиц.', NULL),
        ('option', 'В какой схеме лежит toast-таблица временной таблицы?', '`pg_toast_temp_N`', 'Схема pg_toast_temp_N', 'Аналогично временной схеме pg_temp_N.', NULL),
        ('option', 'В какой схеме лежит toast-таблица временной таблицы?', '`public`', 'Схема public базы данных', 'Toast-таблицы не размещаются в public.', NULL),
        ('option', 'В какой схеме лежит toast-таблица временной таблицы?', '`pg_toast`', 'Схема pg_toast кластера', 'Там лежат toast-таблицы постоянных таблиц.', NULL)
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
